const senderId = String($json.message?.from?.id || '');
const ownerId = String(process.env.OWNER_CHAT_ID || '');

if (!ownerId || senderId !== ownerId) {
  console.warn(`[SECURITY ALERT] Silent drop unauthorized user_id: ${senderId}`);
  return [{ json: { isOwner: false } }];
}
const text = ($json.message?.text || '').trim();
const messageId = $json.message?.message_id;
return [{ json: { isOwner: true, text: text, messageId: messageId } }];

const text = $json.text || '';
let actions = null;

if (text.startsWith('/lock')) {
  actions = [{ action: 'system_power', args: { mode: 'lock' } }];
} else if (text.startsWith('/suspend')) {
  actions = [{ action: 'system_power', args: { mode: 'suspend' } }];
} else if (text.startsWith('/reboot')) {
  actions = [{ action: 'system_power', args: { mode: 'reboot' } }];
} else if (text.startsWith('/shutdown')) {
  actions = [{ action: 'system_power', args: { mode: 'shutdown' } }];
}

return [{ json: { isDirect: actions !== null, actions: actions, text: text } }];

